function furthestRoof(heights: number[], bricks: number, ladders: number): number {
  for (let j = 1; j < heights.length; j++) {
    const climbs: number[] = [];
    for (let i = 0; i < j; i++) if (heights[i + 1] > heights[i]) climbs.push(heights[i + 1] - heights[i]);
    climbs.sort((a, b) => b - a);
    let need = 0;
    for (let k = ladders; k < climbs.length; k++) need += climbs[k];
    if (need > bricks) return j - 1;
  }
  return heights.length - 1;
}

