class MinHeap {
  private a: number[] = [];
  size(): number { return this.a.length; }
  push(x: number): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function furthestRoof(heights: number[], bricks: number, ladders: number): number {
  const heap = new MinHeap(); // climbs currently covered by ladders
  for (let i = 0; i < heights.length - 1; i++) {
    const d = heights[i + 1] - heights[i];
    if (d <= 0) continue;
    heap.push(d);
    if (heap.size() > ladders) {
      bricks -= heap.pop();
      if (bricks < 0) return i;
    }
  }
  return heights.length - 1;
}

